package com.villofarm.model;
import jakarta.persistence.*;import jakarta.validation.constraints.*;import java.math.BigDecimal;
@Entity @Table(name="products") public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@NotBlank private String name;@Column(length=1200) private String description;@NotNull @DecimalMin("0") private BigDecimal price;@NotNull @DecimalMin("0") private BigDecimal originalPrice;@Min(0) private int stock;@NotBlank private String imageUrl;private double rating=5;private int reviewCount=0;private boolean active=true;public Long getId(){return id;}public void setId(Long id){this.id=id;}public String getName(){return name;}public void setName(String name){this.name=name;}public String getDescription(){return description;}public void setDescription(String description){this.description=description;}public BigDecimal getPrice(){return price;}public void setPrice(BigDecimal price){this.price=price;}public BigDecimal getOriginalPrice(){return originalPrice;}public void setOriginalPrice(BigDecimal originalPrice){this.originalPrice=originalPrice;}public int getStock(){return stock;}public void setStock(int stock){this.stock=stock;}public String getImageUrl(){return imageUrl;}public void setImageUrl(String imageUrl){this.imageUrl=imageUrl;}public double getRating(){return rating;}public void setRating(double rating){this.rating=rating;}public int getReviewCount(){return reviewCount;}public void setReviewCount(int reviewCount){this.reviewCount=reviewCount;}public boolean isActive(){return active;}public void setActive(boolean active){this.active=active;} }
